args.script:
awk '
{
    name = $1
    action = $2
    stock = $3
    if (name == "Bob") {
        if (action == "Sell") {
            sold[stock] = 1
        }
        if (action == "Purchase") {
            bought[stock] = 1
        }
    }
}
END {
    count = 0
    for (s in sold) {
        if (!(s in bought)) {
            count++
        }
    }
    print count
}
' /usr/stock.log

awk -F' \\| ' '
{
    name = $1
    action = $3
    stock = $4
    if (name == "Bob") {
        if (action == "Sell") {
            sold[stock] = 1
        }
        if (action == "Purchase") {
            bought[stock] = 1
        }
    }
}
END {
    count = 0
    for (s in sold) {
        if (!(s in bought)) {
            count++
            print "Sold but not bought:", s
        }
    }
    print "Count:", count
}
' /usr/stock.log

